        var acceptedEditorial = workflow.Accept(project, editorial, [family], "Mark approved the disposition"); True(acceptedEditorial.IsCurrentAuthority, "Editorial disposition establishes supplemental authority");

        var scheduleEvidence = new SupplementalEvidence { Kind = SupplementalEvidenceKind.ExpectedSourceDocument, ExpectedDocumentId = scheduleDocument.Id, SourceFamilyId = family.Id, ImportRecordId = scheduleImport.Id, SourceLocator = schedulePath, SourceAsOfUtc = scheduleImport.SourceModifiedUtc, ApplicableSeason = 2026, ApplicableWeek = 1 };
        var schedule = workflow.Stage(project, SupplementalSectionKind.MindenSchedule, new SchedulePayload { TeamOrGroup = "Minden", Games = [new ScheduleEntry { Date = new DateTime(2026, 8, 28), Opponent = "North Webster", Site = "Away", ResultOrTime = "7:00 PM", EvidenceId = scheduleEvidence.Id }] }, [scheduleEvidence]);
        True(workflow.CanAccept(project, schedule, [family], false), "Typed nonempty source-backed schedule is eligible"); var acceptedSchedule = workflow.Accept(project, schedule, [family]); True(acceptedSchedule.IsCurrentAuthority, "Valid source-backed supplemental section accepts normally");

        var page1EditorialEvidence = new SupplementalEvidence { Kind = SupplementalEvidenceKind.EditorialDecision, AuthorityName = "Editor", ApplicableSeason = 2026, ApplicableWeek = 1, Note = "Page 1 editorial direction" };
        var invalidMixedPayload = (Page1WeeklyFactsPayload)ValidPayload(SupplementalSectionKind.Page1WeeklyFacts, page1EditorialEvidence.Id, 2026, 1);
        var invalidMixedPage1 = workflow.Stage(project, SupplementalSectionKind.Page1WeeklyFacts, invalidMixedPayload, [scheduleEvidence, page1EditorialEvidence]);
