        async Task<CompletedGame> AddPersistenceValidLookingBack(GameNotesProject owner, string suffix)
        {
            var fixturePdf = Path.Combine(AppContext.BaseDirectory, "TestFixtures", "Minden vs. Wossman.pdf"); var fixtureText = Path.Combine(AppContext.BaseDirectory, "TestFixtures", "Minden vs. Wossman.txt"); var document = new ExpectedSourceDocument { Name = $"Looking back {suffix}", SourceFamilyId = family.Id, ExpectedLocator = Path.GetFileName(fixturePdf), ResolvedPath = fixturePdf, IsSingleGameReport = true }; document.RefreshStatus(family); owner.ExpectedDocuments.Add(document);
            var import = new ImportRecord { ProjectId = owner.Id, SourceFamilyId = family.Id, ExpectedDocumentId = document.Id, ApplicableSeason = owner.Season, ApplicableWeek = owner.Week, SourceLocator = fixturePdf, SourceModifiedUtc = document.SourceModifiedUtc, ImportedUtc = DateTime.UtcNow, Kind = "PDF-SINGLE-GAME" }; owner.Imports.Add(import); var staged = new SingleGameStatsParser().Parse(await File.ReadAllTextAsync(fixtureText), owner, document, family, import); owner.StagedGameReports.Add(staged); document.SetVerified(true); return new GameInformationWorkflow().Accept(owner, staged, document, family);
        }

