        GameNotesProject CompleteSupplementalProject(int week)
        {
            var owner = CompleteProject(); owner.Season = 2026; owner.Week = week; var doc = new ExpectedSourceDocument { Name = $"Week {week} supplemental source", SourceFamilyId = family.Id, ExpectedLocator = "minden-schedule.pdf" }; doc.RefreshStatus(family); doc.SetVerified(true); owner.ExpectedDocuments.Add(doc);
            foreach (var kind in Enum.GetValues<SupplementalSectionKind>())
            {
                StagedSupplementalSection staged;
                if (kind == SupplementalSectionKind.NerdNotes) staged = workflow.StageEditorial(owner, (NerdNotesPayload)ValidPayload(kind, Guid.Empty, 2026, week), "Mark", $"Week {week} editorial disposition");
                else if (kind == SupplementalSectionKind.Page1WeeklyFacts) staged = workflow.StagePage1(owner, (Page1WeeklyFactsPayload)ValidPayload(kind, Guid.Empty, 2026, week), doc, family, "Mark", $"Week {week} Stat of the Week disposition");
                else staged = workflow.StageSourceBacked(owner, kind, ValidPayload(kind, Guid.Empty, 2026, week), doc, family, kind is SupplementalSectionKind.CoachingHistoryBaseline or SupplementalSectionKind.ProgramHistoryBaseline ? 2025 : null);
                workflow.Accept(owner, staged, [family], kind is SupplementalSectionKind.NerdNotes or SupplementalSectionKind.Page1WeeklyFacts ? "Editorial disposition accepted" : "");
            }
            return owner;
        }

        static SupplementalPayload ValidPayload(SupplementalSectionKind kind, Guid evidenceId, int season, int week) => kind switch
        {
            SupplementalSectionKind.Page1WeeklyFacts => new Page1WeeklyFactsPayload { MindenRecord = new() { Value = "0-0", EvidenceId = evidenceId }, OpponentRecord = new() { Value = "0-0", EvidenceId = evidenceId }, Weather = new() { Temperature = "82", Sky = "Clear", Wind = "S 5", EvidenceId = evidenceId }, OpponentFacts = new() { Rows = [new() { Label = "Coach", Values = ["Coach Name"], EvidenceId = evidenceId }] }, SeriesHistory = [new() { Value = "Minden leads", EvidenceId = evidenceId }], WinImplications = [new() { Value = "Open 1-0", EvidenceId = evidenceId }], StatsOfWeek = [new() { Value = "Verified fact", EvidenceId = evidenceId }], StatOfWeekSelection = new() { Disposition = StatOfWeekDisposition.NoSelection }, ByTheNumbers = [new() { Value = "10 wins", EvidenceId = evidenceId }], PriorSeasonSummary = new() { Value = "5-6", EvidenceId = evidenceId }, SeriesExtremes = new() { Value = "Largest win 20-0", EvidenceId = evidenceId }, Storyline = new() { Value = "Opening week", EvidenceId = evidenceId } },
            SupplementalSectionKind.MindenSchedule or SupplementalSectionKind.OpponentSchedule or SupplementalSectionKind.DistrictSchedule => new SchedulePayload { TeamOrGroup = kind.ToString(), Games = [new() { Date = new DateTime(season, 8, 28), Opponent = "Opponent", Site = "Home", ResultOrTime = "7:00 PM", EvidenceId = evidenceId }] },
            SupplementalSectionKind.Class4APoll or SupplementalSectionKind.DivisionIINonSelectRatings => new RankingSnapshotPayload { Title = kind.ToString(), SourceDate = new DateTime(season, 8, 24), Entries = [new() { Rank = 1, Team = "Team", Record = "0-0", Value = "1", EvidenceId = evidenceId }] },
            SupplementalSectionKind.IndividualOffenseSpecialTeams => new IndividualStatsPayload { ProductionLabel = week == 1 ? "2025 FINAL" : "2026 CUMULATIVE", StatisticalSeason = week == 1 ? season - 1 : season, Tables = [new() { Title = "Rushing", Columns = ["Player", "Yards"], Rows = [new() { Label = "Player", Values = ["100"], EvidenceId = evidenceId }] }] },
            SupplementalSectionKind.PlayerOfGame => new PlayerOfGamePayload { Entries = [new() { Week = 1, Player = "Player", Description = "Performance", EvidenceId = evidenceId }] },
            SupplementalSectionKind.CoachingHistoryBaseline => new CoachingHistoryBaselinePayload { BaselineThroughSeason = season - 1, Sections = [new() { Title = "Heard Era", Rows = [new() { Label = "Record", Values = ["77-66"], EvidenceId = evidenceId }] }] }, SupplementalSectionKind.ProgramHistoryBaseline => new ProgramHistoryBaselinePayload { BaselineThroughSeason = season - 1, Sections = [new() { Title = "Program", Rows = [new() { Label = "Wins", Values = ["569"], EvidenceId = evidenceId }] }] },
            SupplementalSectionKind.TeamStatisticsReport => new TeamStatisticsReportPayload { StatisticalSeason = week == 1 ? season - 1 : season, ReportLabel = week == 1 ? "2025 FINAL" : "2026 CUMULATIVE", Rows = [new() { Label = "First Downs", Minden = "100", Opponent = "90", EvidenceId = evidenceId }] },
            SupplementalSectionKind.NerdNotes => new NerdNotesPayload { EditorialDirection = "Hold all items", Items = [] }, SupplementalSectionKind.MindenRoster or SupplementalSectionKind.OpponentRoster => new RosterPayload { Team = kind == SupplementalSectionKind.MindenRoster ? "Minden" : "Opponent", Season = season, Players = [new() { SourceName = "LAST, FIRST", DisplayName = "First Last", Number = "1", Position = "QB", Grade = "12", EvidenceId = evidenceId }] }, _ => throw new InvalidOperationException()
        };
    }

