        var advisoryPollStage = Stage(monday, SupplementalSectionKind.Class4APoll, "advisory poll replacement"); advisoryPollStage.Issues.Add(new InformationValidationIssue { Severity = InformationIssueSeverity.Advisory, Code = "ReviewedPollAdvisory", Section = "poll", Message = "Reviewed source advisory" }); new SupplementalInformationWorkflow().Accept(monday.Project, advisoryPollStage, [monday.Family], "Advisory reviewed", replace: true); var advisoryHandoff = Rebuild(monday); True(WeeklyProductionHandoffBuilder.Compare(pollReplacement, advisoryHandoff).ChangedPages.Select(x => x.PageNumber).SequenceEqual([2]), "Accepted advisory replacement affects only its dependent page"); True(advisoryHandoff.Pages.Single(x => x.PageNumber == 2).State == PageProductionState.PublicationReady && advisoryHandoff.Pages.Single(x => x.PageNumber == 2).Advisories.Any(x => x.RequirementKey == "P2.Class4APoll"), "Accepted WP 4 advisory remains visible without being converted into a production blocker");

        var pending = Stage(monday, SupplementalSectionKind.OpponentRoster, "pending opponent roster"); var pendingHandoff = Rebuild(monday); True(WeeklyProductionHandoffBuilder.Compare(advisoryHandoff, pendingHandoff).ChangedPages.Count == 0, "Pending supplemental staging cannot affect production state or fingerprints"); new SupplementalInformationWorkflow().Reject(pending, "Rejected test staging"); var rejectedHandoff = Rebuild(monday); True(WeeklyProductionHandoffBuilder.Compare(pendingHandoff, rejectedHandoff).ChangedPages.Count == 0, "Rejected staging cannot affect production state or fingerprints"); True(monday.Project.AcceptedSupplementalSections.Any(x => !x.IsCurrentAuthority) && rejectedHandoff.IsClearedForFinalPublication, "Superseded snapshots remain historical and cannot displace current production authority");

        var rosterDocument = monday.Project.ExpectedDocuments.Single(x => x.Name == SupplementalSectionKind.MindenRoster.ToString()); var rosterPath = rosterDocument.ResolvePath(monday.Family)!; var rosterBytes = await File.ReadAllBytesAsync(rosterPath); var rosterTimestamp = File.GetLastWriteTimeUtc(rosterPath);
        await File.WriteAllTextAsync(rosterPath, "replacement source after acceptance"); File.SetLastWriteTimeUtc(rosterPath, rosterTimestamp.AddMinutes(5)); var replacedSource = Rebuild(monday); var replacedSourceChange = WeeklyProductionHandoffBuilder.Compare(rejectedHandoff, replacedSource); True(replacedSourceChange.ChangedPages.Select(x => x.PageNumber).SequenceEqual([3, 8]) && replacedSource.Pages.Where(x => x.PageNumber is 3 or 8).All(x => x.State == PageProductionState.Waiting), "Live accepted-source replacement is stale and affects exactly Pages 3 and 8 without reload");
