        var originalOpponent = monday.Project.Opponent; monday.Project.Opponent = "Identity Change Opponent"; var identityChanged = Rebuild(monday); var identityComparison = WeeklyProductionHandoffBuilder.Compare(recovered, identityChanged); True(identityComparison.ChangedPages.Select(x => x.PageNumber).SequenceEqual([1]), "Explicit weekly identity changes affect exactly Page 1"); True(identityComparison.ChangedPages.Single().ChangedRequirementKeys.SequenceEqual(["P1.ProjectIdentity"]), "Identity-only comparison reports the exact Page 1 identity requirement"); monday.Project.Opponent = originalOpponent;
        Replace(monday, SupplementalSectionKind.Page1WeeklyFacts, "combined identity and facts replacement"); monday.Project.Opponent = "Combined Identity Change"; var combinedPage1 = Rebuild(monday); var combinedPage1Comparison = WeeklyProductionHandoffBuilder.Compare(recovered, combinedPage1); True(combinedPage1Comparison.ChangedPages.Select(x => x.PageNumber).SequenceEqual([1]), "Combined identity and weekly-facts changes affect Page 1 only"); True(combinedPage1Comparison.ChangedPages.Single().ChangedRequirementKeys.SequenceEqual(["P1.Page1WeeklyFacts", "P1.ProjectIdentity"]), "Page 1 identity reporting is additive when weekly facts change simultaneously"); monday.Project.Opponent = originalOpponent; var stableBeforeAmbiguity = Rebuild(monday);

        var secondTotals = CreateTotals(monday.Family, 2025, Path.Combine(root, "wp5-second-totals.xlsx")); monday.Workspace.Projects.Add(secondTotals.Owner); monday.Project.DefensiveSeasonTotalsAuthorityId = null; var ambiguous = Rebuild(monday); var ambiguityChange = WeeklyProductionHandoffBuilder.Compare(stableBeforeAmbiguity, ambiguous); True(ambiguous.Pages.Single(x => x.PageNumber == 3).State == PageProductionState.Waiting && !ambiguous.IsClearedForFinalPublication, "WP 3 TOTALS ambiguity blocks Page 3 and final clearance"); True(ambiguityChange.ChangedPages.Select(x => x.PageNumber).SequenceEqual([3]) && ambiguityChange.ChangedPages.Single().ChangedRequirementKeys.SequenceEqual(["P3.Defense"]), "WP 3 ambiguity affects exactly Page 3 and P3.Defense"); monday.Project.DefensiveSeasonTotalsAuthorityId = monday.Workspace.Projects.Where(x => x.Id != monday.Project.Id && x.Id != secondTotals.Owner.Id).SelectMany(x => x.AcceptedDefensiveSeasonTotals).Single().Id; var explicitlySelected = Rebuild(monday); var selectionChange = WeeklyProductionHandoffBuilder.Compare(ambiguous, explicitlySelected); True(explicitlySelected.Pages.Single(x => x.PageNumber == 3).State == PageProductionState.PublicationReady, "Explicit WP 3 TOTALS linkage deterministically restores Page 3"); True(selectionChange.ChangedPages.Select(x => x.PageNumber).SequenceEqual([3]) && selectionChange.ChangedPages.Single().ChangedRequirementKeys.SequenceEqual(["P3.Defense"]), "Explicit WP 3 selection affects exactly Page 3 and P3.Defense");

        var weekTwo = await ProductionWorkspace(2, new HashSet<SupplementalSectionKind>(), "week2"); True(weekTwo.Handoff.IsClearedForFinalPublication && weekTwo.Handoff.InformationPackage.Page3.OffenseSpecialTeams?.Payload is IndividualStatsPayload { StatisticalSeason: 2026 } && weekTwo.Handoff.InformationPackage.Page6.TeamStatistics?.Payload is TeamStatisticsReportPayload { StatisticalSeason: 2026 }, "Week 2 production handoff preserves current-season cumulative WP 4 rules"); True(cleared.InformationPackage.Page3.OffenseSpecialTeams?.Payload is IndividualStatsPayload { StatisticalSeason: 2025 } && cleared.InformationPackage.Page6.TeamStatistics?.Payload is TeamStatisticsReportPayload { StatisticalSeason: 2025 }, "Week 1 production handoff preserves prior-season final WP 4 rules");
        var legacy = CompleteProject(); legacy.Season = 2026; legacy.Week = 1; var legacyHandoff = WeeklyProductionHandoffBuilder.Build(WeeklyGameNotesInformationAssembler.Build(new BuilderWorkspace { Projects = [legacy] }, legacy)); True(!legacyHandoff.IsClearedForFinalPublication && legacyHandoff.Pages.Count(x => x.State == PageProductionState.PublicationReady) == 1, "Legacy defaults cannot satisfy production readiness; only factual-not-applicable Page 10 is ready");

        WeeklyProductionHandoff Rebuild((BuilderWorkspace Workspace, GameNotesProject Project, SourceFamilyConfiguration Family, WeeklyProductionHandoff Handoff) context) => WeeklyProductionHandoffBuilder.Build(WeeklyGameNotesInformationAssembler.Build(context.Workspace, context.Project));
        StagedSupplementalSection Stage((BuilderWorkspace Workspace, GameNotesProject Project, SourceFamilyConfiguration Family, WeeklyProductionHandoff Handoff) context, SupplementalSectionKind kind, string marker)
        {
            var document = context.Project.ExpectedDocuments.Single(x => x.Name == kind.ToString()); var payload = ProductionPayload(kind, Guid.Empty, context.Project.Season!.Value, context.Project.Week!.Value, marker); return kind == SupplementalSectionKind.Page1WeeklyFacts ? new SupplementalInformationWorkflow().StagePage1(context.Project, (Page1WeeklyFactsPayload)payload, document, context.Family, "Mark", "Stat of the Week disposition") : new SupplementalInformationWorkflow().StageSourceBacked(context.Project, kind, payload, document, context.Family, kind is SupplementalSectionKind.CoachingHistoryBaseline or SupplementalSectionKind.ProgramHistoryBaseline ? context.Project.Season - 1 : null);
        }
        void AcceptMissing((BuilderWorkspace Workspace, GameNotesProject Project, SourceFamilyConfiguration Family, WeeklyProductionHandoff Handoff) context, SupplementalSectionKind kind, string marker) { var staged = Stage(context, kind, marker); new SupplementalInformationWorkflow().Accept(context.Project, staged, [context.Family], kind is SupplementalSectionKind.NerdNotes or SupplementalSectionKind.Page1WeeklyFacts ? "Editorial disposition accepted" : ""); }
        void Replace((BuilderWorkspace Workspace, GameNotesProject Project, SourceFamilyConfiguration Family, WeeklyProductionHandoff Handoff) context, SupplementalSectionKind kind, string marker) { var staged = Stage(context, kind, marker); new SupplementalInformationWorkflow().Accept(context.Project, staged, [context.Family], kind is SupplementalSectionKind.NerdNotes or SupplementalSectionKind.Page1WeeklyFacts ? "Editorial replacement accepted" : "", replace: true); }

        async Task<(BuilderWorkspace Workspace, GameNotesProject Project, SourceFamilyConfiguration Family, WeeklyProductionHandoff Handoff)> ProductionWorkspace(int week, IReadOnlySet<SupplementalSectionKind> excluded, string suffix)
        {
            var sourceRoot = Path.Combine(root, $"wp5-{suffix}"); Directory.CreateDirectory(sourceRoot); var family = new SourceFamilyConfiguration { Name = $"WP5 {suffix}", RootPath = sourceRoot }; var project = CompleteProject(); project.Season = 2026; project.Week = week; var supplemental = new SupplementalInformationWorkflow();
            foreach (var kind in Enum.GetValues<SupplementalSectionKind>())
            {
                var path = Path.Combine(sourceRoot, $"{kind}.source"); await File.WriteAllTextAsync(path, $"{kind} authoritative source"); var document = new ExpectedSourceDocument { Name = kind.ToString(), SourceFamilyId = family.Id, ExpectedLocator = Path.GetFileName(path) }; document.RefreshStatus(family); document.SetVerified(true); project.ExpectedDocuments.Add(document); if (excluded.Contains(kind)) continue;
                var payload = ProductionPayload(kind, Guid.Empty, 2026, week, suffix); StagedSupplementalSection staged = kind == SupplementalSectionKind.NerdNotes ? supplemental.StageEditorial(project, (NerdNotesPayload)payload, "Mark", "Zero-item disposition") : kind == SupplementalSectionKind.Page1WeeklyFacts ? supplemental.StagePage1(project, (Page1WeeklyFactsPayload)payload, document, family, "Mark", "Stat of the Week disposition") : supplemental.StageSourceBacked(project, kind, payload, document, family, kind is SupplementalSectionKind.CoachingHistoryBaseline or SupplementalSectionKind.ProgramHistoryBaseline ? 2025 : null); supplemental.Accept(project, staged, [family], kind is SupplementalSectionKind.NerdNotes or SupplementalSectionKind.Page1WeeklyFacts ? "Editorial disposition accepted" : "");
            }
            var fixturePdf = Path.Combine(AppContext.BaseDirectory, "TestFixtures", "Minden vs. Wossman.pdf"); var fixtureText = Path.Combine(AppContext.BaseDirectory, "TestFixtures", "Minden vs. Wossman.txt"); var gameDocument = new ExpectedSourceDocument { Name = "WP2 Looking Back", SourceFamilyId = family.Id, ExpectedLocator = Path.GetFileName(fixturePdf), ResolvedPath = fixturePdf, IsSingleGameReport = true }; gameDocument.RefreshStatus(family); project.ExpectedDocuments.Add(gameDocument); var gameImport = new ImportRecord { ProjectId = project.Id, SourceFamilyId = family.Id, ExpectedDocumentId = gameDocument.Id, ApplicableSeason = project.Season, ApplicableWeek = project.Week, SourceLocator = fixturePdf, SourceModifiedUtc = gameDocument.SourceModifiedUtc, ImportedUtc = DateTime.UtcNow, Kind = "PDF-SINGLE-GAME" }; project.Imports.Add(gameImport); var gameStage = new SingleGameStatsParser().Parse(await File.ReadAllTextAsync(fixtureText), project, gameDocument, family, gameImport); project.StagedGameReports.Add(gameStage); gameDocument.SetVerified(true); new GameInformationWorkflow().Accept(project, gameStage, gameDocument, family);
            var totals = CreateTotals(family, week == 1 ? 2025 : 2026, Path.Combine(sourceRoot, "totals.xlsx")); project.DefensiveSeasonTotalsAuthorityId = totals.Totals.Id; var workspace = new BuilderWorkspace { SourceFamilies = [family], Projects = [project, totals.Owner], ActiveProjectId = project.Id }; var store = new ProjectStore(Path.Combine(root, $"wp5-{suffix}.json")); await store.SaveAsync(workspace); workspace = await store.LoadAsync(); project = workspace.ActiveProject!; var package = WeeklyGameNotesInformationAssembler.Build(workspace, project); return (workspace, project, family, WeeklyProductionHandoffBuilder.Build(package));
        }

        (GameNotesProject Owner, AcceptedDefensiveSeasonTotals Totals) CreateTotals(SourceFamilyConfiguration family, int season, string path)
        {
            CreateSectionWorkbook(path, includeTotals: true, totalsSeason: season); var owner = CompleteProject(); owner.Season = season; var document = new ExpectedSourceDocument { Name = Path.GetFileName(path), SourceFamilyId = family.Id, ExpectedLocator = Path.GetFileName(path), ResolvedPath = path }; owner.ExpectedDocuments.Add(document); var stage = new DefensiveWorkbookImportService().Import(path, owner, document, family); document.SetVerified(true); return (owner, new DefensiveInformationWorkflow().AcceptSeasonTotals(owner, stage, document, family));
        }

        static SupplementalPayload ProductionPayload(SupplementalSectionKind kind, Guid evidenceId, int season, int week, string marker) => kind switch
        {
            SupplementalSectionKind.Page1WeeklyFacts => new Page1WeeklyFactsPayload { MindenRecord = new() { Value = "0-0", EvidenceId = evidenceId }, OpponentRecord = new() { Value = "0-0", EvidenceId = evidenceId }, Weather = new() { Temperature = "82", Sky = "Clear", Wind = "S 5", EvidenceId = evidenceId }, OpponentFacts = new() { Rows = [new() { Label = "Coach", Values = [marker], EvidenceId = evidenceId }] }, SeriesHistory = [new() { Value = "Minden leads", EvidenceId = evidenceId }], WinImplications = [new() { Value = "Open 1-0", EvidenceId = evidenceId }], StatsOfWeek = [new() { Value = "Verified fact", EvidenceId = evidenceId }], StatOfWeekSelection = new() { Disposition = StatOfWeekDisposition.NoSelection }, ByTheNumbers = [new() { Value = "10 wins", EvidenceId = evidenceId }], PriorSeasonSummary = new() { Value = "5-6", EvidenceId = evidenceId }, SeriesExtremes = new() { Value = "Largest win", EvidenceId = evidenceId }, Storyline = new() { Value = marker, EvidenceId = evidenceId } },
            SupplementalSectionKind.MindenSchedule or SupplementalSectionKind.OpponentSchedule or SupplementalSectionKind.DistrictSchedule => new SchedulePayload { TeamOrGroup = marker, Games = [new() { Date = new DateTime(season, 8, 28), Opponent = "Opponent", Site = "Home", ResultOrTime = "7 PM", EvidenceId = evidenceId }] }, SupplementalSectionKind.Class4APoll or SupplementalSectionKind.DivisionIINonSelectRatings => new RankingSnapshotPayload { Title = marker, SourceDate = new DateTime(season, 8, 24), Entries = [new() { Rank = 1, Team = "Team", EvidenceId = evidenceId }] },
            SupplementalSectionKind.IndividualOffenseSpecialTeams => new IndividualStatsPayload { ProductionLabel = marker, StatisticalSeason = week == 1 ? season - 1 : season, Tables = [new() { Title = "Rushing", Columns = ["Player", "Yards"], Rows = [new() { Label = "Player", Values = ["100"], EvidenceId = evidenceId }] }] }, SupplementalSectionKind.PlayerOfGame => new PlayerOfGamePayload { Entries = [new() { Week = 1, Player = "Player", Description = marker, EvidenceId = evidenceId }] },
            SupplementalSectionKind.CoachingHistoryBaseline => new CoachingHistoryBaselinePayload { BaselineThroughSeason = season - 1, Sections = [new() { Title = marker, Rows = [new() { Label = "Record", Values = ["77-66"], EvidenceId = evidenceId }] }] }, SupplementalSectionKind.ProgramHistoryBaseline => new ProgramHistoryBaselinePayload { BaselineThroughSeason = season - 1, Sections = [new() { Title = marker, Rows = [new() { Label = "Wins", Values = ["569"], EvidenceId = evidenceId }] }] }, SupplementalSectionKind.TeamStatisticsReport => new TeamStatisticsReportPayload { StatisticalSeason = week == 1 ? season - 1 : season, ReportLabel = marker, Rows = [new() { Label = "First Downs", Minden = "100", Opponent = "90", EvidenceId = evidenceId }] },
            SupplementalSectionKind.NerdNotes => new NerdNotesPayload { EditorialDirection = marker, Items = [] }, SupplementalSectionKind.MindenRoster or SupplementalSectionKind.OpponentRoster => new RosterPayload { Team = marker, Season = season, Players = [new() { SourceName = "LAST, FIRST", DisplayName = "First Last", Number = "1", Position = "QB", Grade = "12", EvidenceId = evidenceId }] }, _ => throw new InvalidOperationException()
        };
    }

    private static void CreateDefensiveWorkbook(string path, bool duplicate, bool totalMismatch, bool invalidStat = false, bool omitBk = false)
    {
        using var zip = ZipFile.Open(path, ZipArchiveMode.Create);
        Write("xl/workbook.xml", """<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Flexible" sheetId="1" r:id="rId1"/></sheets></workbook>""");
        Write("xl/_rels/workbook.xml.rels", """<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>""");
        var total = totalMismatch ? "9" : "3.5"; var duplicateRow = duplicate ? "<row r=\"12\"><c r=\"E12\" t=\"inlineStr\"><is><t>Flexible Player</t></is></c><c r=\"F12\"><v>8</v></c></row>" : ""; var sacks = invalidStat ? "<c r=\"B7\" t=\"inlineStr\"><is><t>bad</t></is></c>" : "<c r=\"B7\"><v>0.5</v></c>"; var bkHeading = omitBk ? "" : "<c r=\"N4\" t=\"inlineStr\"><is><t>BK</t></is></c>";
        Write("xl/worksheets/sheet1.xml", $"""<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="C1" t="inlineStr"><is><t>WEEK 4 - at Flexible Opponent</t></is></c></row><row r="4"><c r="A4" t="inlineStr"><is><t>Total</t></is></c><c r="B4" t="inlineStr"><is><t>Sacks</t></is></c><c r="C4" t="inlineStr"><is><t>Assisted</t></is></c><c r="D4" t="inlineStr"><is><t>Solo</t></is></c><c r="E4" t="inlineStr"><is><t>Name</t></is></c><c r="F4" t="inlineStr"><is><t>#</t></is></c><c r="G4" t="inlineStr"><is><t>TFL</t></is></c><c r="H4" t="inlineStr"><is><t>Hurry</t></is></c><c r="I4" t="inlineStr"><is><t>PBU</t></is></c><c r="J4" t="inlineStr"><is><t>INT</t></is></c><c r="K4" t="inlineStr"><is><t>FF</t></is></c><c r="L4" t="inlineStr"><is><t>FR</t></is></c><c r="M4" t="inlineStr"><is><t>BEP</t></is></c>{bkHeading}</row><row r="7"><c r="A7"><f>SUM(C7:D7)</f><v>{total}</v></c>{sacks}<c r="C7"><v>2</v></c><c r="D7"><v>1.5</v></c><c r="E7" t="inlineStr"><is><t>Flexible Player</t></is></c><c r="F7"><v>7</v></c><c r="G7"><v>0.5</v></c><c r="I7"/><c r="J7"><v>0</v></c><c r="K7"><v>0</v></c><c r="L7"><v>0</v></c><c r="M7"><v>0</v></c><c r="N7"><v>0</v></c></row>{duplicateRow}</sheetData></worksheet>""");
        void Write(string name, string content) { var entry = zip.CreateEntry(name); using var stream = entry.Open(); using var writer = new StreamWriter(stream, Encoding.UTF8); writer.Write(content); }
    }

    private static void CreateSectionWorkbook(string path, bool emptyGame = false, bool emptyTotals = false, bool malformedGame = false, bool malformedTotals = false, string opponent = "Fixture Opponent", decimal gameSolo = 1m, decimal totalsSolo = 1m, bool includeTotals = true, bool includeSecondGame = false, int totalsSeason = 2026)
    {
        using var zip = ZipFile.Open(path, ZipArchiveMode.Create); var sheets = $"<sheet name=\"Game\" sheetId=\"1\" r:id=\"rGame\"/>{(includeSecondGame ? "<sheet name=\"Second\" sheetId=\"2\" r:id=\"rSecond\"/>" : "")}{(includeTotals ? "<sheet name=\"TOTALS\" sheetId=\"3\" r:id=\"rTotals\"/>" : "")}"; var rels = $"<Relationship Id=\"rGame\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet9.xml\"/>{(includeSecondGame ? "<Relationship Id=\"rSecond\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet7.xml\"/>" : "")}{(includeTotals ? "<Relationship Id=\"rTotals\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet4.xml\"/>" : "")}";
        Write("xl/workbook.xml", $"<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>{sheets}</sheets></workbook>"); Write("xl/_rels/workbook.xml.rels", $"<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">{rels}</Relationships>");
        Write("xl/worksheets/sheet9.xml", Sheet($"WEEK 4 - at {opponent}", emptyGame, malformedGame, "Fixture Player", gameSolo));
        if (includeSecondGame) Write("xl/worksheets/sheet7.xml", Sheet("WEEK 5 - Second Opponent", false, false, "Other Player", 1m));
        if (includeTotals) Write("xl/worksheets/sheet4.xml", Sheet($"{totalsSeason} - TOTALS", emptyTotals, malformedTotals, "Fixture Player", totalsSolo));
        static string Sheet(string identity, bool empty, bool malformed, string player, decimal solo)
        {
            var headings = new[] { "Name", "#", "Solo", "Assisted", "Total", "TFL", "Sacks", "Hurry", "PBU", "INT", "FF", "FR", "BEP", "BK" }; var header = string.Concat(headings.Select((x, i) => malformed && i == 13 ? "" : $"<c r=\"{(char)('A' + i)}3\" t=\"inlineStr\"><is><t>{x}</t></is></c>"));
            var row = empty ? "" : $"<row r=\"8\"><c r=\"A8\" t=\"inlineStr\"><is><t>{player}</t></is></c><c r=\"B8\"><v>7</v></c><c r=\"C8\"><v>{solo.ToString(System.Globalization.CultureInfo.InvariantCulture)}</v></c><c r=\"D8\"><v>0</v></c><c r=\"E8\"><f>SUM(C8:D8)</f><v>{solo.ToString(System.Globalization.CultureInfo.InvariantCulture)}</v></c><c r=\"F8\"><v>0</v></c><c r=\"G8\"><v>0</v></c><c r=\"H8\"><v>0</v></c><c r=\"I8\"><v>0</v></c><c r=\"J8\"><v>0</v></c><c r=\"K8\"><v>0</v></c><c r=\"L8\"><v>0</v></c><c r=\"M8\"><v>0</v></c><c r=\"N8\"><v>0</v></c></row>";
            return $"<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData><row r=\"1\"><c r=\"D1\" t=\"inlineStr\"><is><t>{identity}</t></is></c></row><row r=\"3\">{header}</row>{row}</sheetData></worksheet>";
        }
        void Write(string name, string content) { var entry = zip.CreateEntry(name); using var stream = entry.Open(); using var writer = new StreamWriter(stream, Encoding.UTF8); writer.Write(content); }
    }

